<script setup lang="ts">
import { AlertTriangle, ArrowDownRight, ArrowUpRight, Boxes, CircleDollarSign, ClipboardList, RefreshCw, Users } from '@lucide/vue';
const config = useRuntimeConfig();
const route = useRoute();
const { token } = useWorkspaceSession();
const data = ref<any>(null);
const loading = ref(false);
const error = ref('');
const section = computed(() => String(route.query.section || 'overview'));
const titles: Record<string,{eyebrow:string;title:string;description:string}> = {
  overview: { eyebrow:'КОМПАНИЯ / 30 ДНЕЙ', title:'Пульс бизнеса', description:'Ключевые результаты и точки внимания по всей экосистеме' },
  sales: { eyebrow:'ФИНАНСОВЫЙ СРЕЗ', title:'Продажи и каналы', description:'Оборот, количество заказов и вклад каждого канала' },
  customers: { eyebrow:'КЛИЕНТСКАЯ АНАЛИТИКА', title:'Клиенты и развитие', description:'Рост клиентской базы, CRM-нагрузка и качество сервиса' },
};
const title = computed(() => titles[section.value] || titles.overview);
const money = (value: number) => Number(value || 0).toLocaleString('ru-RU', { maximumFractionDigits: 0 });
const channelLabels: Record<string,string> = { WEB:'Интернет-магазин',B2B:'B2B',WILDBERRIES:'Wildberries',OZON:'Ozon',YANDEX_MARKET:'Яндекс Маркет',MEGAMARKET:'Мегамаркет',MANUAL:'Ручной заказ',ONE_C:'1С' };
const salesChannels = computed(() => data.value?.channels || []);
const maxChannelRevenue = computed(() => Math.max(1, ...salesChannels.value.map((item:any) => Number(item.revenue || 0))));
async function load() { loading.value = true; error.value = ''; try { data.value = await $fetch('/leadership/overview', { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${token.value}` } }); } catch (e:any) { error.value = e?.data?.message || 'Не удалось загрузить управленческие показатели'; } finally { loading.value = false; } }
onMounted(load);
</script>

<template><main class="leader-page"><header class="leader-header"><div><p class="eyebrow">{{ title.eyebrow }}</p><h1>{{ title.title }}</h1><span>{{ title.description }}</span></div><button @click="load"><RefreshCw :size="16" :class="{spin:loading}" /> Обновить данные</button></header><WorkspaceLoading v-if="!data && loading" label="Собираем показатели компании" /><div v-else-if="error" class="load-error"><AlertTriangle :size="22" /><span>{{ error }}</span><button @click="load">Повторить</button></div><div v-else-if="data" class="leader-body">
  <template v-if="section === 'overview'"><section class="hero-kpis"><article class="revenue"><span>Оборот за 30 дней</span><strong>{{ money(data.sales.revenue) }} ₽</strong><small :class="data.sales.growth >= 0 ? 'positive' : 'negative'"><ArrowUpRight v-if="data.sales.growth >= 0" :size="14" /><ArrowDownRight v-else :size="14" />{{ Math.abs(data.sales.growth).toFixed(1) }}% к прошлому периоду</small></article><article><ClipboardList :size="19" /><span>Заказы</span><strong>{{ data.sales.orders }}</strong><small>Средний чек {{ money(data.sales.averageOrder) }} ₽</small></article><article><Users :size="19" /><span>Клиенты</span><strong>{{ data.customers.total }}</strong><small>+{{ data.customers.new }} за 30 дней</small></article><article><Boxes :size="19" /><span>Товарные риски</span><strong>{{ data.operations.lowStock }}</strong><small>позиций с малым остатком</small></article></section><section class="overview-grid"><article class="panel"><div class="panel-head"><div><p class="eyebrow">КАНАЛЫ ПРОДАЖ</p><h2>Структура оборота</h2></div><NuxtLink to="/leadership?section=sales">Подробнее</NuxtLink></div><div v-for="item in salesChannels" :key="item.channel" class="channel-row"><div><strong>{{ channelLabels[item.channel] || item.channel }}</strong><small>{{ item.orders }} заказов</small></div><span>{{ money(item.revenue) }} ₽</span><i><b :style="{width:`${Math.max(4, Number(item.revenue || 0) / maxChannelRevenue * 100)}%`}"></b></i></div><p v-if="!salesChannels.length" class="empty">Продажи по каналам пока не зафиксированы</p></article><article class="panel attention"><div class="panel-head"><div><p class="eyebrow">ТРЕБУЕТ ВНИМАНИЯ</p><h2>Операционные риски</h2></div></div><div class="risk"><i class="danger"><AlertTriangle :size="17" /></i><span><strong>Просроченные обращения</strong><small>Нарушен срок решения Helpdesk</small></span><b>{{ data.operations.helpdeskOverdue }}</b></div><div class="risk"><i><HeadphonesIcon /></i><span><strong>Открытые обращения</strong><small>В работе у IT-команды</small></span><b>{{ data.operations.helpdeskOpen }}</b></div><div class="risk"><i><ClipboardList :size="17" /></i><span><strong>Активные задачи</strong><small>Задачи всех подразделений</small></span><b>{{ data.operations.activeTasks }}</b></div><div class="risk"><i><Users :size="17" /></i><span><strong>Открытые лиды</strong><small>Требуют движения по воронке</small></span><b>{{ data.operations.openLeads }}</b></div></article></section></template>
  <template v-else-if="section === 'sales'"><section class="hero-kpis"><article class="revenue"><span>Оборот</span><strong>{{ money(data.sales.revenue) }} ₽</strong><small>За последние 30 дней</small></article><article><CircleDollarSign :size="19" /><span>Прошлый период</span><strong>{{ money(data.sales.previousRevenue) }} ₽</strong><small>База для сравнения</small></article><article><ClipboardList :size="19" /><span>Заказы</span><strong>{{ data.sales.orders }}</strong><small>Все незакрытые продажи</small></article><article><span>Средний чек</span><strong>{{ money(data.sales.averageOrder) }} ₽</strong><small>По всем каналам</small></article></section><article class="panel wide"><div class="panel-head"><div><p class="eyebrow">СРАВНЕНИЕ КАНАЛОВ</p><h2>Продажи по направлениям</h2></div></div><div class="sales-table"><div class="sales-row head"><span>Канал</span><span>Заказы</span><span>Оборот</span><span>Доля</span></div><div v-for="item in salesChannels" :key="item.channel" class="sales-row"><strong>{{ channelLabels[item.channel] || item.channel }}</strong><span>{{ item.orders }}</span><span>{{ money(item.revenue) }} ₽</span><span>{{ data.sales.revenue ? (Number(item.revenue)/data.sales.revenue*100).toFixed(1) : 0 }}%</span></div></div></article></template>
  <template v-else><section class="hero-kpis customer-kpis"><article><Users :size="19" /><span>Клиентская база</span><strong>{{ data.customers.total }}</strong><small>B2C и B2B</small></article><article><ArrowUpRight :size="19" /><span>Новые клиенты</span><strong>{{ data.customers.new }}</strong><small>За последние 30 дней</small></article><article><span>Открытые лиды</span><strong>{{ data.operations.openLeads }}</strong><small>В активной воронке</small></article><article><span>Обращения в поддержку</span><strong>{{ data.operations.helpdeskOpen }}</strong><small>{{ data.operations.helpdeskOverdue }} просрочено</small></article></section><article class="panel wide narrative"><p class="eyebrow">CUSTOMER 360</p><h2>Единая картина клиента</h2><p>Показатели этого раздела будут дополняться повторными покупками, LTV, сегментами, активностью B2B-организаций и качеством поддержки. Все метрики считаются на общих идентификаторах клиентов и заказов.</p></article></template>
</div></main></template>

<script lang="ts">
import { Headphones as HeadphonesIcon } from '@lucide/vue';
export default { components: { HeadphonesIcon } };
</script>

